<?php declare(strict_types=1);
namespace Kulturhus\Verein\Web;
use Kulturhus\Native\Language\MemberCardMessages as Messages;
use Kulturhus\Native\Web\Html;

/** Only public identifiers are retained on refusal. Private files must be selected again. */
final class MemberCardWalletPage
{
    public function __construct(private string $csrf,private array $messages){}
    private function e(string $s):string{return Html::e(Messages::text($s,$this->messages));}
    private function value(mixed $v):string{return is_string($v)&&mb_check_encoding($v,'UTF-8')&&mb_strlen($v)<=300&&!preg_match('/[\x00-\x1f\x7f]|PRIVATE KEY/',$v)?$v:'';}
    private function start(string $action,mixed $version,bool $files=false):string
    {
        $value=$this->value($version);return'<form method="post" autocomplete="off"'.($files?' enctype="multipart/form-data"':'').'>'.Html::hidden('csrf',$this->csrf).Html::hidden('action',$action).Html::hidden('wallet_version',$value);
    }
    private function input(string $name,string $label,mixed $value,int $max=200):string{return'<label>'.$this->e($label).'<input class="form-control" name="'.$name.'" value="'.Html::e($this->value($value)).'" maxlength="'.$max.'" required></label>';}
    private function enabled(mixed $value):string
    {
        $valid=in_array($value,['0','1'],true);$h='<label>'.$this->e('Aktiv').'<select class="form-control" name="enabled" required>';if(!$valid)$h.='<option value="__invalid_original__" selected>'.$this->e('Wallet-Angaben prüfen.').'</option>';foreach(['1'=>'Aktiv','0'=>'Pausiert']as$k=>$label)$h.='<option value="'.$k.'"'.($valid&&$value===(string)$k?' selected':'').'>'.$this->e($label).'</option>';return$h.'</select></label>';
    }
    private function publishing(mixed $v):string{return Html::hidden('publishing_confirmed','0').'<label class="check"><input class="check" type="checkbox" name="publishing_confirmed" value="1"'.($v==='1'?' checked':'').'>'.$this->e('Google-Ausstellerkonto ist für die Nutzung freigeschaltet.').'</label>';}
    public function render(array $state,#[\SensitiveParameter]array $post=[],string $error=''):string
    {
        $h='<link rel="stylesheet" href="member-cards.css"><section class="member-card-settings" data-member-card-wallet-settings><h1>'.$this->e('Mitgliederausweise & Wallet').'</h1><p>'.$this->e('Die private Schlüsseldatei wird verschlüsselt gespeichert und nie angezeigt.').'</p>';if($error!=='')$h.='<p class="error" role="alert">'.$this->e($error).'</p>';$h.='<div class="member-card-wallet-grid">';
        $h.='<p>'.$this->e('Die Wallet-Funktion fügt ausschließlich den Mitgliedsausweis hinzu. Für Apple werden Pass-Zertifikat und Signierschlüssel des Vereins benötigt; für Google ein Wallet-Ausstellerkonto.').'</p>';
        foreach(['apple'=>'Apple Wallet','google'=>'Google Wallet']as$p=>$title){$togglePosted=$removePosted=$toggleStale=$removeStale=false;$s=$state[$p];$action='member-card-wallet-'.$p;$posted=($post['action']??null)===$action;$version=$posted?($post['wallet_version']??null):(string)$s['version'];$stale=false;try{$stale=MemberCardForm::number($version)!==$s['version'];}catch(\DomainException){$stale=true;}$public=$s['public'];$enabled=$posted?($post['enabled']??null):($s['enabled']?'1':'0');$publishing=$posted?($post['publishing_confirmed']??null):(!empty($public['publishing_confirmed'])?'1':'0');
            $h.='<section data-wallet-provider="'.$p.'"><h2>'.$this->e($title).'</h2><p role="status">'.$this->e(!$s['configured']?'Noch nicht eingerichtet':(!$s['enabled']?'Pausiert':($s['ready']?'Für Wallet-Ausgaben bereit':($p==='google'&&!$s['connected']?'Zugang gespeichert · Verbindung noch prüfen.':'Zugang gespeichert · Freigabe bestätigen.')))).'</p>';if($s['checked_at'])$h.='<p>'.$this->e('Zuletzt erfolgreich geprüft').': '.Html::e((new \DateTimeImmutable($s['checked_at'],new \DateTimeZone('UTC')))->setTimezone(new \DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i')).'</p>';
            if($p==='apple'&&!empty($public['certificate_expires_at']))$h.='<p>'.$this->e('Zertifikat gültig bis').': '.Html::e((new \DateTimeImmutable($public['certificate_expires_at']))->setTimezone(new \DateTimeZone('Europe/Berlin'))->format('d.m.Y')).'</p>';
            if($p==='google'&&$s['configured']&&is_string($public['client_email']??null))$h.='<p>'.$this->e('Google-Dienstkonto').': '.Html::e($public['client_email']).'</p>';
            if($p==='google'&&$s['configured']&&empty($public['publishing_confirmed']))$h.='<p>'.$this->e('Freigabe im Google-Ausstellerkonto bestätigen.').'</p>';
            $h.='<details'.(!$s['configured']||$posted?' open':'').'><summary>'.$this->e('Einrichtung speichern').'</summary>';if($stale)$h.='<p role="alert">'.$this->e('Die Einrichtung wurde inzwischen geändert. Deine öffentlichen Angaben bleiben erhalten.').'</p><a class="btn btn-outline theme-secondary" href="?view=settings&amp;tab=member-cards">'.$this->e('Aktuelle Einrichtung öffnen').'</a>';
            $h.=$this->start($action,$version,true).$this->enabled($enabled);
            if($p==='apple'){$h.=$this->input('pass_type_id','Pass Type ID',$posted?($post['pass_type_id']??null):($public['pass_type_id']??''),185).$this->input('team_id','Apple-Team-ID',$posted?($post['team_id']??null):($public['team_id']??''),10).'<label>'.$this->e('Apple-Zertifikat (.p12 oder .pfx)').'<input class="form-control" type="file" name="apple_certificate" accept=".p12,.pfx,application/x-pkcs12" required></label><label>'.$this->e('Passwort der Zertifikatsdatei').'<input class="form-control" type="password" name="apple_password" autocomplete="new-password" maxlength="1000"></label>';}
            else{$h.=$this->input('issuer_id','Google-Aussteller-ID',$posted?($post['issuer_id']??null):($public['issuer_id']??''),30).$this->input('class_id','Google-Ausweisklasse',$posted?($post['class_id']??null):($public['class_id']??''),150).'<label>'.$this->e('Google-Dienstkontodatei (.json)').'<input class="form-control" type="file" name="google_account" accept=".json,application/json" required></label>'.$this->publishing($publishing).'<p>'.$this->e('Das Google-Ausstellerkonto muss außerhalb des Managers freigeschaltet werden. Die Verbindungsprüfung bestätigt den Zugriff auf die gewählte Klasse.').'</p>';}
            $h.='<p>'.$this->e('Bei einem Fehler Datei und Passwort erneut auswählen. Sie werden nicht im Formular übernommen.').'</p><button class="btn btn-solid theme-primary"'.($stale?' disabled':'').'>'.$this->e('Einrichtung speichern').'</button></form></details>';
            if($s['configured']){
                if($p==='google'){$probePosted=($post['action']??null)==='member-card-wallet-probe';$probeVersion=$probePosted?($post['wallet_version']??null):(string)$s['version'];$probeStale=$this->value($probeVersion)!==(string)$s['version'];$h.=$this->start('member-card-wallet-probe',$probeVersion).'<button class="btn btn-outline theme-secondary"'.($probeStale?' disabled':'').'>'.$this->e('Verbindung prüfen').'</button></form>';if($probeStale)$h.='<p role="alert">'.$this->e('Die Einrichtung wurde inzwischen geändert. Deine öffentlichen Angaben bleiben erhalten.').'</p><a class="btn btn-outline theme-secondary" href="?view=settings&amp;tab=member-cards">'.$this->e('Aktuelle Einrichtung öffnen').'</a>'; }
                $togglePosted=($post['action']??null)==='member-card-wallet-toggle'&&($post['provider']??null)===$p;$toggleVersion=$togglePosted?($post['wallet_version']??null):(string)$s['version'];$toggleStale=$this->value($toggleVersion)!==(string)$s['version'];
                $h.='<details'.($togglePosted?' open':'').'><summary>'.$this->e('Aktiv').'</summary>'.$this->start('member-card-wallet-toggle',$toggleVersion).Html::hidden('provider',$p).$this->enabled($togglePosted?($post['enabled']??null):($s['enabled']?'1':'0'));if($p==='google')$h.=$this->publishing($togglePosted?($post['publishing_confirmed']??null):(!empty($public['publishing_confirmed'])?'1':'0'));$h.='<button class="btn btn-outline theme-secondary"'.($toggleStale?' disabled':'').'>'.$this->e('Einrichtung speichern').'</button></form></details>';
                $removePosted=($post['action']??null)==='member-card-wallet-remove'&&($post['provider']??null)===$p;$removeVersion=$removePosted?($post['wallet_version']??null):(string)$s['version'];$removeStale=$this->value($removeVersion)!==(string)$s['version'];$h.='<details'.($removePosted?' open':'').'><summary>'.$this->e('Einrichtung entfernen').'</summary>'.$this->start('member-card-wallet-remove',$removeVersion).Html::hidden('provider',$p).'<label class="check"><input class="check" type="checkbox" name="confirm_remove" value="1"'.($removePosted&&($post['confirm_remove']??null)==='1'?' checked':'').' required>'.$this->e('Vorhandene Einrichtung entfernen? Neue Wallet-Ausgaben sind danach nicht mehr möglich.').'</label><button class="btn btn-outline theme-secondary"'.($removeStale?' disabled':'').'>'.$this->e('Einrichtung entfernen').'</button></form></details>';
            }
            if(($togglePosted??false)&&($toggleStale??false)||($removePosted??false)&&($removeStale??false))$h.='<p role="alert">'.$this->e('Die Einrichtung wurde inzwischen geändert. Deine öffentlichen Angaben bleiben erhalten.').'</p><a class="btn btn-outline theme-secondary" href="?view=settings&amp;tab=member-cards">'.$this->e('Aktuelle Einrichtung öffnen').'</a>';$h.='</section>';
        }
        return$h.'</div></section>';
    }
}
